:root {
  --bg: #fafaf9;
  --card: #ffffff;
  --border: #e7e5e4;
  --text: #1c1917;
  --muted: #78716c;
  --accent: #d97706;
  --success: #059669;
  --warning: #ca8a04;
  --danger: #dc2626;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
}

.app-shell {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 24px;
}

.tagline { color: var(--muted); }

button {
  padding: 10px 16px;
  background: var(--accent);
  color: white;
  border: 0;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
}

button:hover { filter: brightness(0.95); }

pre {
  background: var(--card);
  border: 1px solid var(--border);
  padding: 12px;
  border-radius: 6px;
  overflow-x: auto;
}

