#!/usr/bin/env node
/**
 * Secure local input — collect an API KEY STRING from the user without it
 * passing through chat, a transcript, or an assistant's context.
 *
 * FOR STRINGS ONLY. Keys shown once on a vendor dashboard, passwords, webhook
 * secrets — values the user has to hand over by typing or pasting because they
 * exist somewhere the assistant cannot reach.
 *
 * NOT FOR FILES. If a credential arrives as a downloadable file — a service
 * account JSON, a .pem, a config export — download it yourself and move it into
 * place. It goes vendor -> disk without ever being exposed, so asking the user
 * to open it and paste the contents is invented work. This tool REFUSES file
 * destinations so that mistake cannot be made twice.
 *
 *   node scripts/secure-input.js --spec '<json>'
 *
 * Starts a one-shot HTTP server on 127.0.0.1, opens the browser to it, and
 * waits for a paste. The value goes browser → localhost → destination file.
 * Nothing is logged, echoed, or returned to the caller except a confirmation
 * naming the destination and a length.
 *
 * WHY THIS EXISTS RATHER THAN A POWERSHELL DIALOG
 * -----------------------------------------------
 * WinForms dialogs need STA threading and this project's shell runs
 * non-interactive, so `OpenFileDialog` and `InputBox` return Cancel without
 * ever rendering — silently, which is worse than failing. A local page renders
 * the same way every time, on any OS, and the browser is already open.
 *
 * ORDER OF PREFERENCE, always:
 *   1. Take the value automatically if it can be found (a downloaded key file,
 *      an existing env var). Ask for nothing.
 *   2. Failing that, use this.
 *   3. Never ask for a paste into chat.
 *
 * SECURITY
 *   - binds 127.0.0.1 only, never 0.0.0.0
 *   - random port, random single-use token in the URL; requests without it 404
 *   - shuts down on first successful submit, or after a timeout
 *   - the value is never written to stdout, stderr, or any log
 *   - destination files are written 0600 where the OS honours it
 */

const http = require("http");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { exec } = require("child_process");

// --- spec ------------------------------------------------------------------
// {
//   title:  "Paste your Google Cloud service-account key",
//   help:   "one line of context shown under the title",
//   fields: [{ name, label, hint?, multiline?, kind? }],
//   dest:   { envFile: "F:/…/.env.local" }   // fields become VAR=value
//   timeoutMs?: 600000
// }
const specArg = process.argv.indexOf("--spec");
if (specArg === -1) {
  console.error("usage: secure-input.js --spec '<json>'");
  process.exit(1);
}
const spec = JSON.parse(process.argv[specArg + 1]);
const fields = spec.fields || [];
const TIMEOUT = spec.timeoutMs ?? 10 * 60 * 1000;

if (spec.dest && spec.dest.file) {
  console.error(
    [
      "REFUSED: this tool collects key STRINGS, not files.",
      "A credential that arrives as a file should be downloaded and moved into",
      "place directly — it is never exposed by doing so, and asking the user to",
      "open it and paste the contents is invented work.",
      "Use dest.envFile with a string field instead.",
    ].join("\n")
  );
  process.exit(2);
}

const token = crypto.randomBytes(24).toString("hex");

