// Drive the Chat page end-to-end: type a query, send, wait for card grid,
// confirm results rendered.

export default async function run(page, ui) {
  const before = await ui.snapshot();
  const textareaRef = before.match(/@(e\d+) textbox/)?.[1];
  const sendRef = before.match(/@(e\d+) button "Send"/)?.[1];

  if (!textareaRef || !sendRef) {
    return { error: "textarea or Send button not found", snapshot: before };
  }

  await ui.fill(
    `@${textareaRef}`,
    "Need a licensed electrician in Palm Desert for a kitchen rewire tomorrow"
  );
  await ui.click(`@${sendRef}`);

  // Wait for the assistant response + tool bubble to appear (up to 10s).
  const gotResults = await page
    .waitForSelector("article", { timeout: 15000 })
    .then(() => true)
    .catch(() => false);

  if (!gotResults) {
    return { error: "no <article> (SubcontractorCard) appeared within 15s" };
  }

  // Count how many cards rendered + snapshot a bit of the assistant text.
  const cardCount = await page.$$eval("article", (els) => els.length);
  const assistantText = await page
    .$eval("[class*='rounded-tl-sm'][class*='bg-muted']", (el) => el.textContent?.slice(0, 200) || "")
    .catch(() => "");

  return {
    ok: true,
    cardCount,
    assistantText,
  };
}

