@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    /* Palm Springs at night — warm dark charcoal with cream text + orange accent. */
    --background: 24 12% 7%;
    --foreground: 30 20% 92%;

    --card: 24 10% 10%;
    --card-foreground: 30 20% 92%;

    --popover: 24 10% 10%;
    --popover-foreground: 30 20% 92%;

    --primary: 24 95% 55%;
    --primary-foreground: 24 12% 7%;

    --secondary: 24 8% 14%;
    --secondary-foreground: 30 20% 92%;

    --muted: 24 8% 14%;
    --muted-foreground: 30 8% 65%;

    --accent: 24 8% 18%;
    --accent-foreground: 30 20% 92%;

    --destructive: 0 62% 55%;
    --destructive-foreground: 30 20% 92%;

    --success: 158 55% 55%;
    --success-foreground: 24 12% 7%;

    --border: 24 8% 16%;
    --input: 24 8% 16%;
    --ring: 24 95% 55%;

    --radius: 0.5rem;
  }

  /* Preserve a .dark class for API compat, but our default IS dark. */
  .dark {
    --background: 24 12% 7%;
    --foreground: 30 20% 92%;
    --card: 24 10% 10%;
    --card-foreground: 30 20% 92%;
    --popover: 24 10% 10%;
    --popover-foreground: 30 20% 92%;
    --primary: 24 95% 55%;
    --primary-foreground: 24 12% 7%;
    --secondary: 24 8% 14%;
    --secondary-foreground: 30 20% 92%;
    --muted: 24 8% 14%;
    --muted-foreground: 30 8% 65%;
    --accent: 24 8% 18%;
    --accent-foreground: 30 20% 92%;
    --destructive: 0 62% 55%;
    --destructive-foreground: 30 20% 92%;
    --success: 158 55% 55%;
    --success-foreground: 24 12% 7%;
    --border: 24 8% 16%;
    --input: 24 8% 16%;
    --ring: 24 95% 55%;
  }
}

@layer base {
  * { @apply border-border; }
  html {
    font-family: "Jost", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
    font-feature-settings: "cv11", "ss01";
    font-weight: 400;
  }
  body {
    @apply bg-background text-foreground antialiased;
    letter-spacing: -0.005em;
  }
  h1, h2, h3, h4, h5, h6 {
    font-weight: 500;
    letter-spacing: -0.02em;
  }
}

